function validate([paths]) {
  if (!Array.isArray(paths) || paths.length < 1 || paths.length > 100) return 'paths needs 1 to 100 roads.';
  const next = new Map(), arrivals = new Set();
  for (const path of paths) {
    if (!Array.isArray(path) || path.length !== 2) return 'Each road is a pair [cityA, cityB].';
    for (const city of path) if (typeof city !== 'string' || city.length < 1 || city.length > 10 || !/^[A-Za-z ]+$/.test(city)) return 'Each city name has 1 to 10 letters or spaces.';
    if (path[0] === path[1]) return 'A road must join two different cities.';
    if (next.has(path[0])) return 'At most one road may leave each city.';
    if (arrivals.has(path[1])) return 'At most one road may arrive at each city.';
    next.set(path[0], path[1]);
    arrivals.add(path[1]);
  }
  const starts = [...next.keys()].filter(city => !arrivals.has(city));
  if (starts.length !== 1) return 'The roads must form one chain without a loop.';
  let city = starts[0], visited = 1;
  while (next.has(city)) { city = next.get(city); visited++; }
  if (visited !== paths.length + 1) return 'The roads must form one chain without a loop.';
  return null;
}

