function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 6);
  const letters = size === 'large' ? 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ' : 'abAB';
  const pick = () => letters[Math.floor(rand() * letters.length)];
  const name = () => {
    const length = 1 + Math.floor(rand() * (size === 'large' ? 10 : 3));
    let text = '';
    for (let i = 0; i < length; i++) text += i > 0 && i < length - 1 && rand() < 0.15 ? ' ' : pick();
    return text;
  };
  // n + 1 distinct cities visited in order make a chain of n roads.
  const seen = new Set(), cities = [];
  while (cities.length < n + 1) {
    const city = name();
    if (!seen.has(city)) { seen.add(city); cities.push(city); }
  }
  const paths = [];
  for (let i = 0; i < n; i++) paths.push([cities[i], cities[i + 1]]);
  for (let i = paths.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [paths[i], paths[j]] = [paths[j], paths[i]];
  }
  return [paths];
}
